import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {spawnSync} from 'node:child_process';
import {openStore} from '../lib/store.js';import {createBundleService} from '../lib/bundles.js';
const settle=async(service,id)=>{for(let i=0;i<500;i++){const job=service.get(id);if(!['queued','running'].includes(job.status))return job;await new Promise(r=>setTimeout(r,4));}throw Error('Bundle worker did not settle');};
function saveExport(store,project,jobId,name,bytes='actual exported video',reviewed=true){const output=store.putAsset(Buffer.from(bytes),'video/mp4'),srt=store.putAsset(Buffer.from('1\n00:00:00,000 --> 00:00:01,000\nReviewed words\n'),'text/plain');store.putRecord('export_result',jobId,{...output,projectId:project.id,name:name+'.mp4'});store.putRecord('export_job',jobId,{id:jobId,status:'complete',projectId:project.id,name,format:'mp4',output,srt,moments:[{showCaptions:true,captionLanguage:'English',captionReviewed:{English:reviewed},captionCues:{English:[{start:0,end:1,text:'Reviewed words'}]}}]});return {output,srt};}
function archive(file){const result=spawnSync('python3',['-c',`import zipfile,json,sys
with zipfile.ZipFile(sys.argv[1]) as z:
 print(json.dumps({'files':z.namelist(),'contents':{n:z.read(n).decode('utf8') for n in z.namelist()},'bad':z.testzip()}))`,file],{encoding:'utf8'});assert.equal(result.status,0,result.stderr);return JSON.parse(result.stdout);}
test('bulk bundle contains genuine selected exports, safe unique names, reviewed SRT and local provenance',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-content-')),store=openStore(root);try{
  const project=store.createProject({title:'Episode'});saveExport(store,project,'one','../../same & name','first video');saveExport(store,project,'two','../../same & name','second video',false);
  const service=createBundleService({store}),request={projectId:project.id,exportIds:['two','one'],name:'Episode: bulk / review'},job=service.start(request);assert.equal(service.start(request).id,job.id);
  const done=await settle(service,job.id);assert.equal(done.status,'complete',done.error);assert.equal(done.kind,'bundle');assert.equal(done.output.type,'application/zip');assert.match(done.output.name,/\.zip$/);assert.equal(service.counts().completed,1);
  const contents=archive(store.assetPath(done.output.id).file);assert.equal(contents.bad,null);assert.equal(contents.files.filter(n=>n.endsWith('.mp4')).length,2);assert.equal(contents.files.filter(n=>n.endsWith('.srt')).length,1);assert.ok(contents.files.every(n=>!n.includes('/')&&!n.includes('..')&&!n.startsWith('-')));assert.equal(contents.contents[contents.files.find(n=>n.startsWith('001-')&&n.endsWith('.mp4'))],'second video');assert.equal(contents.contents[contents.files.find(n=>n.startsWith('002-')&&n.endsWith('.mp4'))],'first video');
  const manifest=JSON.parse(contents.contents['context-desk-manifest.json']);assert.equal(manifest.projectId,project.id);assert.deepEqual(manifest.exports.map(e=>e.exportId),['two','one']);assert.match(done.warnings.join(' '),/review/i);await assert.rejects(fs.access(path.join(root,'bundles',job.id)));
 }finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
test('selection validates project ownership and local project-export URLs, never arbitrary assets or paths',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-ownership-')),store=openStore(root);try{
  const p=store.createProject(),other=store.createProject(),mine=saveExport(store,p,'mine','Mine'),foreign=saveExport(store,other,'foreign','Other','other project media'),orphan=store.putAsset(Buffer.from('not an export'),'video/mp4'),service=createBundleService({store});
  for(const body of [{exportIds:['foreign']},{exportUrls:[foreign.output.url]},{exportUrls:[orphan.url]},{exportUrls:['file:///etc/passwd']},{exportIds:[]},{exportIds:Array(501).fill('mine')},{exportIds:['../../etc/passwd']}])assert.throws(()=>service.start({projectId:p.id,...body}),/project|export|Choose|saved|local/i);
  const job=service.start({projectId:p.id,exportUrls:[mine.output.url],includeSubtitles:false});const done=await settle(service,job.id);assert.equal(done.status,'complete',done.error);assert.equal(archive(store.assetPath(done.output.id).file).files.filter(n=>n.endsWith('.srt')).length,0);
 }finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
test('asset symlinks are refused instead of following unrelated local files',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-symlink-')),store=openStore(root);try{const p=store.createProject(),saved=saveExport(store,p,'symlink','Clip'),assetFile=store.assetPath(saved.output.id).file;await fs.unlink(assetFile);await fs.symlink('/etc/passwd',assetFile);const service=createBundleService({store}),job=service.start({projectId:p.id,exportIds:['symlink']});const done=await settle(service,job.id);assert.equal(done.status,'error');assert.match(done.error,/symbolic|symlink|regular|local/i);assert.equal(done.output,null);}finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
test('queued and running cancellation leaves no archive or staging files and permits an explicit retry',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-cancel-')),store=openStore(root);try{
  const p=store.createProject();saveExport(store,p,'clip','Clip');const service=createBundleService({store}),queued=service.start({projectId:p.id,exportIds:['clip'],name:'queued'});service.command(queued.id,'cancel');assert.equal(service.get(queued.id).status,'cancelled');
  const job=service.start({projectId:p.id,exportIds:['clip'],name:'running'});await new Promise(r=>setImmediate(r));assert.equal(service.get(job.id).status,'running');service.command(job.id,'cancel');const cancelled=await settle(service,job.id);assert.equal(cancelled.status,'cancelled');assert.equal(cancelled.output,null);await assert.rejects(fs.access(path.join(root,'bundles',job.id)));
  service.command(job.id,'resume');const done=await settle(service,job.id);assert.equal(done.status,'complete',done.error);assert.equal(service.counts().cancelled,1);
 }finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
test('restart interrupts unfinished bundles, cleans partial disk output and waits for explicit resume',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-restart-'));let store=openStore(root);try{
  const p=store.createProject();saveExport(store,p,'clip','Clip');const service=createBundleService({store}),job=service.start({projectId:p.id,exportIds:['clip']});service.command(job.id,'pause');await new Promise(r=>setImmediate(r));const document=store.getRecord('bundle_job',job.id);store.putRecord('bundle_job',job.id,{...document,status:'running',inFlight:null});await fs.mkdir(path.join(root,'bundles',job.id),{recursive:true});await fs.writeFile(path.join(root,'bundles',job.id,'partial.zip'),'broken');await fs.writeFile(path.join(root,'assets','.bundle-'+job.id+'.tmp'),'partial');store.close();
  store=openStore(root);const recovered=createBundleService({store});assert.equal(recovered.get(job.id).status,'interrupted');await assert.rejects(fs.access(path.join(root,'bundles',job.id)));await assert.rejects(fs.access(path.join(root,'assets','.bundle-'+job.id+'.tmp')));await new Promise(r=>setImmediate(r));assert.equal(recovered.get(job.id).status,'interrupted');recovered.command(job.id,'resume');assert.equal((await settle(recovered,job.id)).status,'complete');
 }finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});

test('missing reviewed subtitle files are omitted with a warning while video packaging still completes',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-missing-srt-')),store=openStore(root);try{const p=store.createProject(),saved=saveExport(store,p,'clip','Clip');await fs.unlink(store.assetPath(saved.srt.id).file);const service=createBundleService({store}),job=service.start({projectId:p.id,exportIds:['clip']});const done=await settle(service,job.id);assert.equal(done.status,'complete',done.error);const zipped=archive(store.assetPath(done.output.id).file);assert.equal(zipped.files.filter(n=>n.endsWith('.srt')).length,0);assert.equal(JSON.parse(zipped.contents['context-desk-manifest.json']).exports[0].subtitles,null);assert.match(done.warnings.join(' '),/unavailable on disk/);}finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
test('insufficient free space stops before packaging and the durable job can resume after space recovers',async()=>{
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-disk-')),store=openStore(root);let available=false;try{const p=store.createProject();saveExport(store,p,'clip','Clip');const service=createBundleService({store,statfs:async file=>available?fs.statfs(file):{bavail:1,bsize:4096}}),job=service.start({projectId:p.id,exportIds:['clip']});const stopped=await settle(service,job.id);assert.equal(stopped.status,'error');assert.match(stopped.error,/free disk space/);assert.equal(stopped.output,null);await assert.rejects(fs.access(path.join(root,'bundles',job.id)));available=true;service.command(job.id,'resume');assert.equal((await settle(service,job.id)).status,'complete');}finally{store.close();await fs.rm(root,{recursive:true,force:true})}
});
